1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Service 在 Store 之上实现班次交接的全部业务规则。
11	type Service struct {
12		store *Store
13		now   func() time.Time
14	}
15	
16	// NewService 创建业务服务。
17	func NewService(store *Store) *Service {
18		return &Service{store: store, now: time.Now}
19	}
20	
21	// nowAt 供测试固定处理时间。
22	func (svc *Service) nowAt(fn func() time.Time) { svc.now = fn }
23	
24	func clean(s string) string { return strings.TrimSpace(s) }
25	
26	func requireNonEmpty(field, v string) error {
27		if clean(v) == "" {
28			return fmt.Errorf("%w：%s不能为空", ErrInvalidInput, field)
29		}
30		return nil
31	}
32	
33	func intervalsOverlap(s1, e1, s2, e2 time.Time) bool {
34		// 前班结束恰好等于后班开始（端点相等）不算重叠。
35		return s1.Before(e2) && s2.Before(e1)
36	}
37	
38	// notePair 返回无序班次编号对，作为重叠说明的稳定键。
39	func notePair(a, b string) (string, string) {
40		if a <= b {
41			return a, b
42		}
43		return b, a
44	}
45	
46	func findShift(d *Data, id string) (*Shift, int) {
47		for i := range d.Shifts {
48			if d.Shifts[i].ID == id {
49				return &d.Shifts[i], i
50			}
51		}
52		return nil, -1
53	}
54	
55	func findItem(d *Data, id string) (*Item, int) {
56		for i := range d.Items {
57			if d.Items[i].ID == id {
58				return &d.Items[i], i
59			}
60		}
61		return nil, -1
62	}
63	
64	func findHandover(d *Data, id string) (*Handover, int) {
65		for i := range d.Handovers {
66			if d.Handovers[i].ID == id {
67				return &d.Handovers[i], i
68			}
69		}
70		return nil, -1
71	}
72	
73	func findEntry(h *Handover, itemID string) (*HandoverEntry, int) {
74		for i := range h.Entries {
75			if h.Entries[i].ItemID == itemID {
76				return &h.Entries[i], i
77			}
78		}
79		return nil, -1
80	}
81	
82	func findNote(d *Data, a, b string) *OverlapNote {
83		x, y := notePair(a, b)
84		for i := range d.Notes {
85			if d.Notes[i].ShiftA == x && d.Notes[i].ShiftB == y {
86				return &d.Notes[i]
87			}
88		}
89		return nil
90	}
91	
92	// currentItemsOfShift 返回与某班次相关的当前事项，按编号排列、每项只列一次。
93	// 用于进行中班次的当前信息展示，以及缺少结束时记录的旧数据班次。
94	func currentItemsOfShift(d *Data, shiftID string) []Item {
95		out := []Item{}
96		seen := map[string]bool{}
97		for _, it := range d.Items {
98			if seen[it.ID] {
99				continue
100			}
101			if it.OriginShiftID == shiftID || it.CurrentShiftID == shiftID || contains(it.ShiftIDs, shiftID) {
102				seen[it.ID] = true
103				out = append(out, it)
104			}
105		}
106		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
107		return out
108	}
109	
110	func hasNote(d *Data, a, b string) bool { return findNote(d, a, b) != nil }
111	
112	// CreateShift 建立班次。岗位、负责人必填，结束时间必须晚于开始时间。
113	// 同一岗位按实际时刻比较区间：前班结束恰好等于后班开始不算重叠；
114	// 与同岗位已存班次存在重叠时 overlapNote 必须非空，说明会一并保存。
115	// 不同岗位互不影响。
116	func (svc *Service) CreateShift(position, owner string, start, end time.Time, overlapNote string) (Shift, error) {
117		position = clean(position)
118		owner = clean(owner)
119		overlapNote = clean(overlapNote)
120		if err := requireNonEmpty("岗位", position); err != nil {
121			return Shift{}, err
122		}
123		if err := requireNonEmpty("负责人", owner); err != nil {
124			return Shift{}, err
125		}
126		if !end.After(start) {
127			return Shift{}, fmt.Errorf("%w：结束时间必须晚于开始时间（开始 %s，结束 %s）",
128				ErrInvalidInput, start.Format(time.RFC3339), end.Format(time.RFC3339))
129		}
130	
131		var created Shift
132		err := svc.store.mutate(func(d *Data) error {
133			var overlapping []Shift
134			for _, sh := range d.Shifts {
135				if sh.Position == position && intervalsOverlap(start, end, sh.Start, sh.End) {
136					overlapping = append(overlapping, sh)
137				}
138			}
139			if len(overlapping) > 0 && overlapNote == "" {
140				ids := make([]string, len(overlapping))
141				for i, sh := range overlapping {
142					ids[i] = fmt.Sprintf("%s（%s ~ %s）", sh.ID, sh.Start.Format(time.RFC3339), sh.End.Format(time.RFC3339))
143				}
144				return fmt.Errorf("%w：与同岗位班次 %s 区间重叠，必须填写重叠说明",
145					ErrOverlap, strings.Join(ids, "、"))
146			}
147	
148			d.ShiftSeq++
149			now := svc.now()
150			created = Shift{
151				ID:        fmt.Sprintf("S%03d", d.ShiftSeq),
152				Position:  position,
153				Owner:     owner,
154				Start:     start,
155				End:       end,
156				CreatedAt: now,
157			}
158			d.Shifts = append(d.Shifts, created)
159	
160			// 为每个尚未登记说明的重叠班次保存说明；已有说明的不重复保存。
161			for _, sh := range overlapping {
162				if findNote(d, created.ID, sh.ID) != nil {
163					continue
164				}
165				d.NoteSeq++
166				x, y := notePair(created.ID, sh.ID)
167				d.Notes = append(d.Notes, OverlapNote{
168					ID:        fmt.Sprintf("N%03d", d.NoteSeq),
169					Position:  position,
170					ShiftA:    x,
171					ShiftB:    y,
172					Note:      overlapNote,
173					CreatedAt: now,
174				})
175			}
176			return nil
177		})
178		return created, err
179	}
180	
181	// AddOverlapNote 为同岗位两个重叠班次保存重叠说明。
182	func (svc *Service) AddOverlapNote(shiftA, shiftB, note string) (OverlapNote, error) {
183		note = clean(note)
184		if err := requireNonEmpty("重叠说明", note); err != nil {
185			return OverlapNote{}, err
186		}
187		if clean(shiftA) == clean(shiftB) {
188			return OverlapNote{}, fmt.Errorf("%w：重叠说明需要两个不同的班次", ErrInvalidInput)
189		}
190	
191		var saved OverlapNote
192		err := svc.store.mutate(func(d *Data) error {
193			sa, _ := findShift(d, clean(shiftA))
194			sb, _ := findShift(d, clean(shiftB))
195			if sa == nil || sb == nil {
196				return fmt.Errorf("%w：班次 %s 或 %s 不存在", ErrNotFound, shiftA, shiftB)
197			}
198			if sa.Position != sb.Position {
199				return fmt.Errorf("%w：班次 %s（%s）与 %s（%s）岗位不同，无需重叠说明",
200					ErrPositionMismatch, sa.ID, sa.Position, sb.ID, sb.Position)
201			}
202			if !intervalsOverlap(sa.Start, sa.End, sb.Start, sb.End) {
203				return fmt.Errorf("%w：班次 %s 与 %s 的时间区间不重叠（端点相接不算重叠）",
204					ErrInvalidInput, sa.ID, sb.ID)
205			}
206			d.NoteSeq++
207			x, y := notePair(sa.ID, sb.ID)
208			saved = OverlapNote{
209				ID:        fmt.Sprintf("N%03d", d.NoteSeq),
210				Position:  sa.Position,
211				ShiftA:    x,
212				ShiftB:    y,
213				Note:      note,
214				CreatedAt: svc.now(),
215			}
216			d.Notes = append(d.Notes, saved)
217			return nil
218		})
219		return saved, err
220	}
221	
222	// AddItem 向未结束班次新增事项。内容、严重程度、后续负责人必填，限制条件可空。
223	func (svc *Service) AddItem(shiftID, content string, severity Severity, constraints, followOwner string) (Item, error) {
224		shiftID = clean(shiftID)
225		content = clean(content)
226		constraints = clean(constraints)
227		followOwner = clean(followOwner)
228		if err := requireNonEmpty("事项内容", content); err != nil {
229			return Item{}, err
230		}
231		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
232			return Item{}, err
233		}
234		if !severity.valid() {
235			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
236		}
237	
238		var created Item
239		err := svc.store.mutate(func(d *Data) error {
240			sh, _ := findShift(d, shiftID)
241			if sh == nil {
242				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
243			}
244			if sh.Closed {
245				return fmt.Errorf("%w：班次 %s 已结束，不能新增事项", ErrShiftClosed, sh.ID)
246			}
247			d.ItemSeq++
248			now := svc.now()
249			created = Item{
250				ID:             fmt.Sprintf("I%03d", d.ItemSeq),
251				OriginShiftID:  sh.ID,
252				ShiftIDs:       []string{sh.ID},
253				CurrentShiftID: sh.ID,
254				Content:        content,
255				Severity:       severity,
256				Constraints:    constraints,
257				FollowOwner:    followOwner,
258				CreatedAt:      now,
259				Events: []ItemEvent{
260					{At: now, Kind: "created", Detail: "事项建立"},
261				},
262			}
263			d.Items = append(d.Items, created)
264			return nil
265		})
266		return created, err
267	}
268	
269	// UpdateItem 在事项所在班次结束前修改其内容、严重程度、限制条件和后续负责人。
270	func (svc *Service) UpdateItem(itemID, content string, severity Severity, constraints, followOwner string) (Item, error) {
271		itemID = clean(itemID)
272		content = clean(content)
273		constraints = clean(constraints)
274		followOwner = clean(followOwner)
275		if err := requireNonEmpty("事项内容", content); err != nil {
276			return Item{}, err
277		}
278		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
279			return Item{}, err
280		}
281		if !severity.valid() {
282			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
283		}
284	
285		var updated Item
286		err := svc.store.mutate(func(d *Data) error {
287			it, _ := findItem(d, itemID)
288			if it == nil {
289				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
290			}
291			sh, _ := findShift(d, it.CurrentShiftID)
292			if sh == nil || sh.Closed {
293				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，内容不能修改",
294					ErrShiftClosed, itemID, it.CurrentShiftID)
295			}
296			changes := []string{}
297			if it.Content != content {
298				changes = append(changes, "内容")
299			}
300			if it.Severity != severity {
301				changes = append(changes, "严重程度")
302			}
303			if it.Constraints != constraints {
304				changes = append(changes, "限制条件")
305			}
306			if it.FollowOwner != followOwner {
307				changes = append(changes, "后续负责人")
308			}
309			it.Content = content
310			it.Severity = severity
311			it.Constraints = constraints
312			it.FollowOwner = followOwner
313			it.Events = append(it.Events, ItemEvent{
314				At:     svc.now(),
315				Kind:   "updated",
316				Detail: "修改字段：" + joinOr(changes, "无变更"),
317			})
318			updated = *it
319			return nil
320		})
321		return updated, err
322	}
323	
324	func joinOr(xs []string, or string) string {
325		if len(xs) == 0 {
326			return or
327		}
328		return strings.Join(xs, "、")
329	}
330	
331	// CloseItem 在事项所在班次结束前关闭该事项，须填写操作人。
332	func (svc *Service) CloseItem(itemID, operator string) (Item, error) {
333		itemID = clean(itemID)
334		operator = clean(operator)
335		if err := requireNonEmpty("操作人", operator); err != nil {
336			return Item{}, err
337		}
338	
339		var closed Item
340		err := svc.store.mutate(func(d *Data) error {
341			it, _ := findItem(d, itemID)
342			if it == nil {
343				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
344			}
345			if it.Closed {
346				return fmt.Errorf("%w：事项 %s 已关闭，不能重复关闭", ErrHandoverState, itemID)
347			}
348			sh, _ := findShift(d, it.CurrentShiftID)
349			if sh == nil || sh.Closed {
350				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，关闭状态不能修改",
351					ErrShiftClosed, itemID, it.CurrentShiftID)
352			}
353			now := svc.now()
354			it.Closed = true
355			it.ClosedAt = &now
356			it.CloseOperator = operator
357			it.Events = append(it.Events, ItemEvent{At: now, Kind: "closed", Operator: operator})
358			closed = *it
359			return nil
360		})
361		return closed, err
362	}
363	
364	// CloseShift 结束班次。接班交接仍有待处理或退回项时不允许结束；空清单也可以结束。
365	// 结束成功时把在班事项（本班新增与已接收，含结束前已关闭者）冻结为结束时记录；
366	// 校验或保存失败时不留下任何记录，班次保持进行中。
367	func (svc *Service) CloseShift(shiftID string) (Shift, error) {
368		shiftID = clean(shiftID)
369		var result Shift
370		err := svc.store.mutate(func(d *Data) error {
371			sh, _ := findShift(d, shiftID)
372			if sh == nil {
373				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
374			}
375			if sh.Closed {
376				return fmt.Errorf("%w：班次 %s 已结束", ErrShiftClosed, sh.ID)
377			}
378			for i := range d.Handovers {
379				h := &d.Handovers[i]
380				if h.ToShiftID == sh.ID && !h.Completed() {
381					return fmt.Errorf("%w：接班交接 %s 仍有未处理或退回事项，班次不能结束",
382						ErrHandoverState, h.ID)
383				}
384			}
385			now := svc.now()
386			sh.Closed = true
387			sh.ClosedAt = &now
388	
389			// 冻结结束时在班的全部事项。退回或未确认的交接事项当前班次仍在交班
390			// 班次，不会被快照；结束前已关闭的事项保留关闭人与关闭时间。
391			record := &ShiftCloseRecord{Items: []CloseItemSnapshot{}}
392			for i := range d.Items {
393				it := &d.Items[i]
394				if it.CurrentShiftID != sh.ID {
395					continue
396				}
397				record.Items = append(record.Items, CloseItemSnapshot{
398					ItemID:        it.ID,
399					Content:       it.Content,
400					Severity:      it.Severity,
401					Constraints:   it.Constraints,
402					FollowOwner:   it.FollowOwner,
403					Closed:        it.Closed,
404					ClosedAt:      it.ClosedAt,
405					CloseOperator: it.CloseOperator,
406				})
407			}
408			sort.Slice(record.Items, func(i, j int) bool { return record.Items[i].ItemID < record.Items[j].ItemID })
409			sh.CloseRecord = record
410	
411			result = *sh
412			return nil
413		})
414		return result, err
415	}
416	
417	// CreateHandover 由交班班次向同岗位接班班次发起交接。
418	// 重复向同一接班班次发起返回已有记录；改换接班对象报错。
419	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
420		fromShiftID = clean(fromShiftID)
421		toShiftID = clean(toShiftID)
422	
423		var result Handover
424		err := svc.store.mutate(func(d *Data) error {
425			from, _ := findShift(d, fromShiftID)
426			to, _ := findShift(d, toShiftID)
427			if from == nil {
428				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
429			}
430			if to == nil {
431				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
432			}
433			if from.ID == to.ID {
434				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
435			}
436			if from.Position != to.Position {
437				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
438					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
439			}
440			if to.Closed {
441				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
442			}
443			if to.Start.Before(from.Start) {
444				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
445					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
446					from.ID, from.Start.Format(time.RFC3339))
447			}
448	
449			// 同一交班班次只能指定一个接班对象。
450			for i := range d.Handovers {
451				if d.Handovers[i].FromShiftID == from.ID {
452					existing := &d.Handovers[i]
453					result = *existing
454					if existing.ToShiftID != to.ID {
455						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
456							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
457					}
458					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
459				}
460			}
461	
462			if !from.Closed {
463				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
464					ErrShiftNotClosed, from.ID)
465			}
466			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasNote(d, from.ID, to.ID) {
467				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
468					ErrOverlap, from.ID, to.ID)
469			}
470	
471			entries := []HandoverEntry{}
472			for i := range d.Items {
473				it := &d.Items[i]
474				if it.CurrentShiftID == from.ID && !it.Closed {
475					entries = append(entries, HandoverEntry{
476						ItemID:      it.ID,
477						Content:     it.Content,
478						Severity:    it.Severity,
479						Constraints: it.Constraints,
480						FollowOwner: it.FollowOwner,
481						Status:      EntryPending,
482					})
483				}
484			}
485			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
486	
487			d.HandoverSeq++
488			now := svc.now()
489			h := Handover{
490				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
491				Position:    from.Position,
492				FromShiftID: from.ID,
493				ToShiftID:   to.ID,
494				CreatedAt:   now,
495				Entries:     entries,
496			}
497			if len(entries) == 0 {
498				// 空清单直接完成。
499				h.CompletedAt = &now
500			}
501			d.Handovers = append(d.Handovers, h)
502			result = h
503			return nil
504		})
505		return result, err
506	}
507	
508	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
509	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
510	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
511	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
512	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
513		handoverID = clean(handoverID)
514		itemID = clean(itemID)
515		operator = clean(operator)
516		reason = clean(reason)
517		trackingNote = clean(trackingNote)
518		nextFollowOwner = clean(nextFollowOwner)
519	
520		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
521			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
522		}
523		if err := requireNonEmpty("操作人", operator); err != nil {
524			return Handover{}, err
525		}
526	
527		var result Handover
528		err := svc.store.mutate(func(d *Data) error {
529			h, _ := findHandover(d, handoverID)
530			if h == nil {
531				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
532			}
533			e, _ := findEntry(h, itemID)
534			if e == nil {
535				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
536			}
537			if e.Status.Received() {
538				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
539					ErrHandoverState, e.ItemID, e.Status.Label())
540			}
541			if e.Status == EntryReturned {
542				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
543				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
544				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
545				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
546					ErrHandoverState, e.ItemID, h.ID)
547			}
548			switch action {
549			case ActionReturn:
550				if err := requireNonEmpty("退回原因", reason); err != nil {
551					return err
552				}
553			case ActionTrack:
554				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
555					return err
556				}
557				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
558					return err
559				}
560			}
561	
562			now := svc.now()
563			switch action {
564			case ActionConfirm:
565				e.Status = EntryConfirmed
566			case ActionTrack:
567				e.Status = EntryTracking
568				e.TrackingNote = trackingNote
569				e.FollowOwner = nextFollowOwner
570			case ActionReturn:
571				e.Status = EntryReturned
572				e.Rounds = append(e.Rounds, ReturnRound{
573					Seq:            len(e.Rounds) + 1,
574					ReturnedAt:     now,
575					ReturnOperator: operator,
576					Reason:         reason,
577				})
578			}
579			e.Operator = operator
580			e.ProcessedAt = &now
581	
582			if action != ActionReturn {
583				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
584				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
585					it.CurrentShiftID = h.ToShiftID
586					if !contains(it.ShiftIDs, h.ToShiftID) {
587						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
588					}
589					detail := "接班班次 " + h.ToShiftID + " 接收：" + e.Status.Label()
590					if action == ActionTrack {
591						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
592						it.FollowOwner = nextFollowOwner
593						detail += "；跟踪说明：" + trackingNote + "；后续负责人：" + nextFollowOwner
594					}
595					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
596				}
597			}
598	
599			if h.Completed() && h.CompletedAt == nil {
600				h.CompletedAt = &now
601			}
602			result = *h
603			return nil
604		})
605		return result, err
606	}
607	
608	func contains(xs []string, x string) bool {
609		for _, v := range xs {
610			if v == x {
611				return true
612			}
613		}
614		return false
615	}
616	
617	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
618	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
619	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
620	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
621	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
622	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
623	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
624		handoverID = clean(handoverID)
625		itemID = clean(itemID)
626		operator = clean(operator)
627		supplement = clean(supplement)
628		if err := requireNonEmpty("操作人", operator); err != nil {
629			return Handover{}, err
630		}
631		if err := requireNonEmpty("补充说明", supplement); err != nil {
632			return Handover{}, err
633		}
634	
635		var result Handover
636		err := svc.store.mutate(func(d *Data) error {
637			h, _ := findHandover(d, handoverID)
638			if h == nil {
639				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
640			}
641			e, _ := findEntry(h, itemID)
642			if e == nil {
643				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
644			}
645			if e.Status != EntryReturned {
646				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
647					ErrHandoverState, e.ItemID, e.Status.Label())
648			}
649			if len(e.Rounds) == 0 {
650				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
651			}
652			round := &e.Rounds[len(e.Rounds)-1]
653			if round.ResubmittedAt != nil {
654				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
655			}
656			now := svc.now()
657			round.Supplement = supplement
658			round.SupplementOperator = operator
659			round.SupplementAt = &now
660			round.ResubmittedAt = &now
661			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
662			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
663			e.Status = EntryPending
664			e.Operator = ""
665			e.ProcessedAt = nil
666			result = *h
667			return nil
668		})
669		return result, err
670	}
671	
672	// GetShift 按编号查询班次。
673	func (svc *Service) GetShift(id string) (Shift, error) {
674		sh, _ := findShift(&svc.store.data, clean(id))
675		if sh == nil {
676			return Shift{}, fmt.Errorf("%w：班次 %s", ErrNotFound, id)
677		}
678		return *sh, nil
679	}
680	
681	// ListShifts 返回全部班次，按编号排序。
682	func (svc *Service) ListShifts() []Shift {
683		out := append([]Shift(nil), svc.store.data.Shifts...)
684		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
685		return out
686	}
687	
688	// GetItem 按稳定编号查询事项。
689	func (svc *Service) GetItem(id string) (Item, error) {
690		it, _ := findItem(&svc.store.data, clean(id))
691		if it == nil {
692			return Item{}, fmt.Errorf("%w：事项 %s", ErrNotFound, id)
693		}
694		return *it, nil
695	}
696	
697	// GetHandover 按编号查询交接。
698	func (svc *Service) GetHandover(id string) (Handover, error) {
699		h, _ := findHandover(&svc.store.data, clean(id))
700		if h == nil {
701			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
702		}
703		return *h, nil
704	}
705	
706	// ListHandovers 返回全部交接记录，按编号排序。
707	func (svc *Service) ListHandovers() []Handover {
708		out := append([]Handover(nil), svc.store.data.Handovers...)
709		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
710		return out
711	}
712	
713	// OverlapNotes 返回涉及指定班次的全部重叠说明。
714	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
715		shiftID = clean(shiftID)
716		out := []OverlapNote{}
717		for _, n := range svc.store.data.Notes {
718			if n.ShiftA == shiftID || n.ShiftB == shiftID {
719				out = append(out, n)
720			}
721		}
722		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
723		return out
724	}
725	
726	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
727	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
728	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
729	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
730		shiftID = clean(shiftID)
731		d := &svc.store.data
732		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
733		sh, _ := findShift(d, shiftID)
734		if sh == nil {
735			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
736		}
737		rep.Shift = *sh
738	
739		for _, n := range d.Notes {
740			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
741				rep.OverlapNotes = append(rep.OverlapNotes, n)
742			}
743		}
744		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
745	
746		switch {
747		case !sh.Closed:
748			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
749			rep.Items = currentItemsOfShift(d, sh.ID)
750		case sh.CloseRecord != nil:
751			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
752			rep.ItemsAtClose = true
753			rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
754			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
755			for _, s := range rep.CloseItems {
756				if it, _ := findItem(d, s.ItemID); it != nil {
757					rep.LatestItems[s.ItemID] = *it
758				}
759			}
760		default:
761			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
762			rep.HistoryIncomplete = true
763			rep.Items = currentItemsOfShift(d, sh.ID)
764		}
765		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
766	
767		for i := range d.Handovers {
768			h := &d.Handovers[i]
769			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
770			if !involved {
771				continue
772			}
773			if h.FromShiftID == sh.ID {
774				cp := *h
775				rep.Outgoing = &cp
776			}
777			if h.ToShiftID == sh.ID {
778				rep.Incoming = append(rep.Incoming, *h)
779			}
780			for j := range h.Entries {
781				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
782					HandoverID: h.ID,
783					FromShift:  h.FromShiftID,
784					ToShift:    h.ToShiftID,
785					Entry:      h.Entries[j],
786				})
787			}
788		}
789		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
790		for k := range rep.Results {
791			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
792		}
793		return rep, nil
794	}
