199		}
200		for _, h := range rep.Incoming {
201			b.WriteString(indentLines(FormatHandover(h), "  "))
202		}
203	
204		b.WriteString("\n各项交接当前结果：\n")
205		if len(rep.Results) == 0 {
206			b.WriteString("  （无）\n")
207		}
208		ids := make([]string, 0, len(rep.Results))
209		for id := range rep.Results {
210			ids = append(ids, id)
211		}
212		sort.Strings(ids)
213		for _, id := range ids {
214			views := rep.Results[id]
215			for _, v := range views {
216				operator, processedAt := dashIfEmpty(v.Entry.Operator), fmtTimePtr(v.Entry.ProcessedAt)
217				if v.Entry.ProcessedAt == nil {
218					operator, processedAt = "尚未处理", "尚未处理"
219				}
220				fmt.Fprintf(&b, "  事项 %s 交接 %s（%s -> %s）当前结果：%s；处理人=%s；处理时间=%s\n",
221					id, v.HandoverID, v.FromShift, v.ToShift,
222					v.Entry.Status.Label(), operator, processedAt)
223				for _, r := range v.Entry.Rounds {
224					fmt.Fprintf(&b, "    第%d次退回：操作人=%s 时间=%s 原因=%s\n",
225						r.Seq, r.ReturnOperator, fmtTime(r.ReturnedAt), r.Reason)
226					if r.Supplement != "" {
227						fmt.Fprintf(&b, "      补充：%s（补充人=%s，补充时间=%s）\n",
228							r.Supplement, dashIfEmpty(r.SupplementOperator), fmtTimePtr(r.SupplementAt))
229					}
230					if r.ResubmittedAt != nil {
231						fmt.Fprintf(&b, "      已重新提交：%s\n", fmtTime(*r.ResubmittedAt))
232					}
233				}
234			}
235		}
236		return b.String()
237	}
