478		if _, err := f.svc.ResubmitReturned(h.ID, idA, " 张三 ", "图纸编号已补到资料柜B层"); err != nil {
479			t.Fatalf("resubmit: %v", err)
480		}
481		got, _ = f.svc.GetHandover(h.ID)
482		var ea, eb *HandoverEntry
483		for i := range got.Entries {
