511		}
512		got, _ = f.svc.GetHandover(h.ID)
513		for i := range got.Entries {
514			if got.Entries[i].ItemID == idA {
515				ea = &got.Entries[i]
516			}
517		}
518		if len(ea.Rounds) != 2 {
519			t.Fatalf("应保留历次退回记录，期望2轮，got %d", len(ea.Rounds))
520		}
521		if ea.Rounds[0].Reason != "信息不全，需补充图纸" {
522			t.Fatalf("第一轮退回原因不得覆盖：%+v", ea.Rounds[0])
523		}
524		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "签字已补齐"); err != nil {
525			t.Fatalf("resubmit2: %v", err)
526		}
527		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionConfirm, "李四", "", "", ""); err != nil {
528			t.Fatalf("final confirm: %v", err)
529		}
530		got, _ = f.svc.GetHandover(h.ID)
531		if !got.Completed() {
532			t.Fatalf("最终应完成")
533		}
534	}
